import gurobipy as gp
from gurobipy import GRB
suppliers = []
dealerships = []
demand = {}
fixed_cost = {}
cost = {}
for rec in LEGACY_RECORDS:
    src = rec['source']
    vals = rec['values']
    if src.endswith('demand.csv'):
        cust = vals['customer']
        if cust not in dealerships:
            dealerships.append(cust)
        demand[cust] = int(vals['demand'])
    elif src.endswith('fixed_cost.csv'):
        sup = vals['Unnamed: 0']
        if sup not in suppliers:
            suppliers.append(sup)
        fixed_cost[sup] = float(vals['fixed_costs'])
    elif src.endswith('transportation_costs.csv'):
        sup = vals['Unnamed: 0']
        if sup not in suppliers:
            suppliers.append(sup)
        if sup not in cost:
            cost[sup] = {}
        for j in vals:
            if j != 'Unnamed: 0':
                if j not in dealerships:
                    dealerships.append(j)
                cost[sup][j] = float(vals[j])
for i in suppliers:
    if i not in cost:
        raise ValueError(f'Missing cost row for supplier {i}')
    for j in dealerships:
        if j not in cost[i]:
            raise ValueError(f'Missing cost entry for supplier {i}, dealership {j}')
for i in suppliers:
    if i not in fixed_cost:
        raise ValueError(f'Missing fixed cost for supplier {i}')
for j in dealerships:
    if j not in demand:
        raise ValueError(f'Missing demand for dealership {j}')
M = sum((demand[j] for j in dealerships))
m = gp.Model('ColoradoMotorVehicleSales_UFLP')
x_vars = m.addVars(suppliers, dealerships, lb=0, vtype=GRB.CONTINUOUS, name='')
y_vars = m.addVars(suppliers, vtype=GRB.BINARY, name='')
m.setObjective(gp.quicksum((cost[i][j] * x_vars[i, j] for i in suppliers for j in dealerships)) + gp.quicksum((fixed_cost[i] * y_vars[i] for i in suppliers)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x_vars[i, j] for i in suppliers)) == demand[j] for j in dealerships), name='')
m.addConstrs((gp.quicksum((x_vars[i, j] for j in dealerships)) <= M * y_vars[i] for i in suppliers), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')